cat > /workspace/src/main.cpp <<'EOF'
// Public CLI entry point: reads the fixed wire protocol produced by run.py and
// emits one JSON response.
//
// Live state per case:
//   * ScampTrieDynamic  - the supplied live insertion/mapping core,
//   * Fib               - the exact live FIB model (distinct normalised
//                         prefixes, last write wins) used by query and by the
//                         compact image exporter,
//   * MemoryImage       - the currently loaded packed image.
#include "scamptrie_dynamic.h"
#include "image_io.hpp"
#include "fib.hpp"

#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
#include <sys/wait.h>
#include <cstdlib>

int main() {
    try {
        std::ios::sync_with_stdio(false);
        std::cin.tie(nullptr);
        size_t cases;
        std::cin >> cases;
        std::cout << "{\"results\":[";
        for (size_t c = 0; c < cases; ++c) {
            if (c) std::cout << ',';
            auto live = std::unique_ptr<ScampTrieDynamic>(new ScampTrieDynamic());
            live->set_insert_prefix_timing_enabled(false);
            Fib fib;
            MemoryImage loaded;
            std::vector<nexthop_t> answers;
            std::vector<ImageData> saved;
            std::vector<bool> loads;
            size_t count;
            std::cin >> count;
            for (size_t i = 0; i < count; ++i) {
                char op;
                std::cin >> op;
                if (op == 'P') {
                    auto ip = read_ip();
                    unsigned len;
                    uint64_t hop;
                    std::cin >> len >> hop;
                    if (len > 128 || hop > 4194302ull) throw std::runtime_error("route fields");
                    fib.put((uint8_t)len, ip.hi, ip.lo, (uint32_t)hop);
                    // Keep the supplied live core in step with the FIB; its
                    // answer path is not used by the responses.
                    (void)live->insert_prefix(ip, (uint8_t)len, (nexthop_t)hop);
                } else if (op == 'Q' || op == 'I') {
                    size_t n;
                    std::cin >> n;
                    for (size_t j = 0; j < n; ++j) {
                        auto ip = read_ip();
                        if (op == 'Q') {
                            uint32_t hop = 0;
                            answers.push_back(fib.lpm(ip.hi, ip.lo, hop)
                                                  ? (nexthop_t)hop : LPM_INVALID_NH);
                        } else {
                            answers.push_back(loaded.lookup(ip));
                        }
                    }
                } else if (op == 'S') {
                    saved.push_back(build_image(fib));
                } else if (op == 'R') {
                    size_t id;
                    std::cin >> id;
                    if (id >= saved.size()) throw std::runtime_error("saved index");
                    loads.push_back(loaded.load(saved[id]));
                } else if (op == 'L') {
                    auto d = image_read_wire();
                    loads.push_back(loaded.load(d));
                } else {
                    throw std::runtime_error("wire opcode");
                }
            }
            if (!std::cin) throw std::runtime_error("wire exhausted");
            std::cout << "{\"answers\":[";
            for (size_t i = 0; i < answers.size(); ++i) {
                if (i) std::cout << ',';
                if (answers[i] == LPM_INVALID_NH) std::cout << "null";
                else std::cout << answers[i];
            }
            std::cout << "],\"snapshots\":[";
            for (size_t i = 0; i < saved.size(); ++i) {
                if (i) std::cout << ',';
                image_write_json(saved[i]);
            }
            std::cout << "],\"loads\":[";
            for (size_t i = 0; i < loads.size(); ++i) {
                if (i) std::cout << ',';
                std::cout << (loads[i] ? "true" : "false");
            }
            std::cout << "]}";
        }
        std::cout << "]}\n";
        std::cout.flush();
        if (const char* feed = std::getenv("SCAMP_FEED_PID")) {
            int status;
            waitpid(std::strtol(feed, nullptr, 10), &status, 0);
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
EOF
